import socket,struct
import fcntl

def get_ip(ifname):
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
    return socket.inet_ntoa(fcntl.ioctl(s.fileno(),0x8915,struct.pack('256s',ifname[:15].encode()))[20:24])

def get_mask(ifname):
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
    return socket.inet_ntoa(fcntl.ioctl(s.fileno(),0x891b,struct.pack('256s',ifname[:15].encode()))[20:24])

for ifn in ['eth0','lo']:
    try:
        print(ifn, get_ip(ifn), get_mask(ifn))
    except Exception as e:
        print(ifn, 'err', e)
